// Parse the AI output string into actual JSON key-value pairs
let parsedData = {};
try {
  parsedData = JSON.parse($json.output);
  parsedData.is_json = true;
} catch (e) {
  // If it's plain text (multi-turn follow-up chat), retain raw text
  parsedData = {
    is_json: false,
    text_reply: $json.output
  };
}

return parsedData;

// Retrieve AI output from earlier Code node
const aiOutput = $("Format AI Response").first().json;

// Check Airtable search output
const airtableRecord = $("Search records for previous complaint").first().json;

// Extract Airtable Record ID (falls back to undefined if search returned no records)
const airtableId = airtableRecord ? airtableRecord.id : undefined;

// If Airtable returned a record with data, check for prior negative feedback
const hasHistory = Boolean(
  airtableRecord && 
  airtableRecord.id !== undefined && 
  airtableRecord.fields && 
  airtableRecord.fields["Has Prior Negative Feedback"] === true
);

return {
  ...aiOutput,
  id: airtableId,
  has_prior_negative_feedback: hasHistory
};
